const NL = String.fromCharCode(10);
const items = $input.all();
const e = (items[0] && items[0].json) || {};
const wf = e.workflow || {};
const ex = e.execution || {};
const err = ex.error || {};
function esc(s) { return String(s == null ? '' : s).split('&').join('&amp;').split('<').join('&lt;').split('>').join('&gt;'); }
function clip(s, n) { s = String(s == null ? '' : s).trim(); return s.length > n ? s.slice(0, n - 1).trimEnd() + '...' : s; }
const isTest = !items.length || !wf.name;
const name = wf.name || 'Test run - no failure behind this';
const step = ex.lastNodeExecuted || 'n/a';
const msg = clip(err.message || 'No error message returned', 600);
const url = ex.url || '';
const blocks = [
  { type: 'header', text: { type: 'plain_text', text: isTest ? 'Alert test' : 'Workflow failed', emoji: true } },
  { type: 'section', text: { type: 'mrkdwn', text: '*' + esc(name) + '*' + NL + 'Failed at step: *' + esc(step) + '*' } },
  { type: 'section', text: { type: 'mrkdwn', text: '*Error*' + NL + esc(msg) } }
];
if (url) {
  blocks.push({ type: 'actions', elements: [ { type: 'button', text: { type: 'plain_text', text: 'Open execution', emoji: false }, url: url, style: 'primary' } ] });
}
blocks.push({ type: 'context', elements: [ { type: 'mrkdwn', text: isTest ? 'Manual test of the alert workflow - nothing actually failed' : 'n8n error alert - fires on production runs only, once per failed run' } ] });
const fallback = (isTest ? 'Alert test - ' : '') + name + ' failed at ' + step + ' - ' + clip(msg, 120);
return [{ json: { workflow_name: name, failed_step: step, error_message: msg, execution_url: url, is_test: isTest, slack_blocks: JSON.stringify({ blocks: blocks }), slack_fallback: fallback } }];
